package com.cyclone.teamworksniper.data

import android.content.Context
import android.content.SharedPreferences
import com.cyclone.teamworksniper.rules.RuleJson
import org.json.JSONArray
import org.json.JSONObject

private const val PREFS="teamwork_sniper"; private const val RULES="rules_json"; private const val ENABLED="sniper_enabled"; private const val ARMED="sniper_armed"; private const val ACTIVITY="activity_json"; private const val MAX=100
fun sniperPreferences(context:Context):SharedPreferences=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE)
class RuleStore(context:Context){private val p=sniperPreferences(context); fun load()=RuleJson.decode(p.getString(RULES,null)); fun save(v:List<ShiftRule>){p.edit().putString(RULES,RuleJson.encode(v)).apply()}}
class SettingsStore(context:Context){private val p=sniperPreferences(context); fun load()=SniperSettings(p.getBoolean(ENABLED,true),p.getBoolean(ARMED,false)); fun save(v:SniperSettings){p.edit().putBoolean(ENABLED,v.enabled).putBoolean(ARMED,v.armed).apply()}}
class ActivityLogStore(context:Context){private val p=sniperPreferences(context); @Synchronized fun append(e:ActivityEntry){save((listOf(e)+load()).take(MAX))}; @Synchronized fun load():List<ActivityEntry>{val raw=p.getString(ACTIVITY,null)?:return emptyList(); return runCatching{val a=JSONArray(raw); buildList{for(i in 0 until a.length())decode(a.optJSONObject(i)?:continue)?.let(::add)}}.getOrDefault(emptyList())}; private fun save(v:List<ActivityEntry>){val a=JSONArray();v.forEach{a.put(encode(it))};p.edit().putString(ACTIVITY,a.toString()).apply()}; private fun encode(e:ActivityEntry)=JSONObject().apply{put("id",e.id);put("source",e.triggerSource.name);put("time",e.triggerEpochMs);putN("title",e.notificationTitle.safe());putN("text",e.notificationText.safe());putN("openLatency",e.teamworkOpenLatencyMs);putN("compareLatency",e.firstComparisonLatencyMs);putN("evaluationDuration",e.evaluationDurationMs);putN("claimDuration",e.claimDurationMs);put("shifts",JSONArray(e.openShifts));put("rules",JSONArray(e.evaluatedRules));put("decision",e.decision);put("armed",e.armedState);put("attempted",e.claimAttempted);putN("claim",e.claimResult);putN("verify",e.verificationResult);putN("failure",e.failureReason)}; private fun decode(j:JSONObject):ActivityEntry?{val s=runCatching{TriggerSource.valueOf(j.getString("source"))}.getOrNull()?:return null;return ActivityEntry(j.optString("id"),s,j.optLong("time"),j.s("title"),j.s("text"),j.l("openLatency"),j.l("compareLatency"),j.l("evaluationDuration"),j.l("claimDuration"),j.optJSONArray("shifts").strings(),j.optJSONArray("rules").strings(),j.optString("decision"),j.optBoolean("armed"),j.optBoolean("attempted"),j.s("claim"),j.s("verify"),j.s("failure"))}}
private fun JSONObject.putN(k:String,v:Any?){put(k,v?:JSONObject.NULL)}; private fun JSONObject.s(k:String)=if(isNull(k))null else optString(k).takeIf{it.isNotBlank()}; private fun JSONObject.l(k:String)=if(isNull(k)||!has(k))null else optLong(k); private fun JSONArray?.strings():List<String>{if(this==null)return emptyList();return buildList{for(i in 0 until length())optString(i).takeIf{it.isNotBlank()}?.let(::add)}}; private fun String?.safe():String?{if(isNullOrBlank())return null;val l=lowercase();if(listOf("password","verification code","one-time code","otp").any(l::contains))return null;return replace(Regex("\\s+")," ").trim().take(200)}
